                    ctx,
                    element.0,
                    end,
                    DecodeFlavor::Clip { clip_rule: true },
                    transform,
                    &style,
                    &mut expansions,
                    control,
                )?;
            }
            DefinitionKind::Mask => {
                if next_mask >= 1024 {
                    return Err(crate::limit(LimitKind::Masks, tok.name.offset));
                }
                if bounds[2] <= bounds[0] || bounds[3] <= bounds[1] {
                    return Err(unsupported(tok.name.offset));
