                    .iter()
                    .enumerate()
                {
                    if let Some(s) = attr(source, tokens, element.0, key) {
                        custom = true;
                        region[i] = mask_region(
                            source,
                            s,
                            units,
                            if i % 2 == 0 {
                                ctx.builder.scene(ctx.scene)?.viewport.width as f64
