    reference: f64,
) -> Result<f64> {
    if object_bbox {
        let b = span_bytes(src, span).ok_or_else(|| bad(span.offset))?;
        let pct = b.last() == Some(&b'%');
        let s = if pct {
            XmlSpan {
                offset: span.offset,
                length: span.length - 1,
            }
        } else {
            span
        };
        let n = parse_number(src, s, 0.)?;
        Ok(if pct { n / 100. } else { n })
    } else {
        let b = span_bytes(src, span).ok_or_else(|| bad(span.offset))?;
        if b.last() == Some(&b'%') {
            return Ok(parse_number(
                src,
                XmlSpan {
                    offset: span.offset,
                    length: span.length - 1,
                },
                0.,
            )? * reference
                / 100.);
        }
        parse_length(src, span, reference)
    }
}
