pub fn plan<'src, 'ctx>(
    &mut self,
    ctx: &mut DefinitionContext<'src, 'ctx>,
    kind: DefinitionKind,
    element: ElementId,
    owner: ShapeId,
    transform: Affine,
    bounds: [f64; 4],
    _style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
) -> Result<DefinitionPlan<'src>> {
    let mut charges = AllocationJournal::new();
    match self.plan_inner(ctx, kind, element, owner, transform, bounds, control, &mut charges) {
        Ok((plan, _)) => {
            let retained = plan_capacity_bytes(&plan)?;
            if let Err(error) = charges.admit_bytes(ctx.ledger, retained) {
                charges.rollback(ctx.ledger);
                return Err(error);
            }
            charges.commit();
            Ok(plan)
        }
        Err(error) => {
            charges.rollback(ctx.ledger);
            Err(error)
        }
    }
}

